local ServiceScope = {}
ServiceScope.__index = ServiceScope

function ServiceScope.new(serviceProvider: ServiceProvider)
	local self = setmetatable({}, ServiceScope)
	self._serviceProvider = serviceProvider
	self._disposed = false
	return self
end

function ServiceScope:Dispose()
	if self._disposed then
		return
	end
	self._disposed = true

	-- 1. 从父级 Provider 的 scopes 中移除自己
	local parent = self._serviceProvider.Parent
	if parent then
		parent._scopes[self] = nil
	end

	-- 2. 销毁自己的 Provider
	if not self._serviceProvider.DisposeCalled then
		self._serviceProvider:Dispose()
	end
end

function ServiceScope:GetService(serviceType: string)
	local service = self._serviceProvider:GetService(serviceType)
	if not service then
		service = self._serviceProvider.Parent:GetRequiredService(serviceType)
	end
	return service
end

function ServiceScope:GetRequiredService(serviceType: string)
	local service = self._serviceProvider:GetRequiredService(serviceType)
	if not service then
		service = self._serviceProvider.Parent:GetService(serviceType)
	end
	return service
end

function ServiceScope:GetServiceProvider()
	return self._serviceProvider
end

return ServiceScope
